  state.condition??={};if((state.condition[state.selected]??100)<=0){toast('Оружие сломано. Нужен ремонтный стол.');return;}state.condition[state.selected]=Math.max(0,(state.condition[state.selected]??100)-(w.projectile?2:.25));setMagazine(state,state.selected,magazine(state)-1);attackCooldown=w.interval;world.swing=.22;audio.burst(.22,1,3100);audio.tone(80,.15,.4,'sawtooth');haptic(35);
