function drawMap(){
 const c=$('map-canvas'),ctx=c.getContext('2d');ctx.fillStyle='#172f2b';ctx.fillRect(0,0,600,520);const unit=235/WORLD_RADIUS,ox=300,oz=260;
 for(let x=-WORLD_RADIUS;x<WORLD_RADIUS;x+=WORLD_RADIUS/90)for(let z=-WORLD_RADIUS;z<WORLD_RADIUS;z+=WORLD_RADIUS/90){const h=terrainHeight(x,z);if(h<.1)continue;const n=clamp((h+1)/30,0,1),biome=biomeAt(x,z);ctx.fillStyle=h<.85?'#cdb782':biome.id==='snow'?'#d7e3e5':biome.id==='arid'?'#cfa763':biome.id==='coast'?'#b7a67a':`rgb(${52+n*50},${91+n*45},${54+n*28})`;ctx.fillRect(ox+x*unit,oz+z*unit,unit*WORLD_RADIUS/90+1,unit*WORLD_RADIUS/90+1);}
 ctx.strokeStyle='#d3ddaa16';ctx.lineWidth=1;for(let i=0;i<600;i+=50){ctx.beginPath();ctx.moveTo(i,0);ctx.lineTo(i,520);ctx.stroke();}for(let i=0;i<520;i+=50){ctx.beginPath();ctx.moveTo(0,i);ctx.lineTo(600,i);ctx.stroke();}
 const marker=(x,z,text,color)=>{ctx.fillStyle=color;ctx.beginPath();ctx.arc(ox+x*unit,oz+z*unit,4,0,6.28);ctx.fill();ctx.font='9px Arial';ctx.fillText(text,ox+x*unit+10,oz+z*unit+3);};
 for(const path of Object.values(ROADS)){ctx.strokeStyle='#b2a67999';ctx.lineWidth=2;ctx.beginPath();path.forEach((p,i)=>i?ctx.lineTo(ox+p.x*unit,oz+p.z*unit):ctx.moveTo(ox+p.x*unit,oz+p.z*unit));ctx.stroke();}for(const m of MONUMENTS)marker(m.x,m.z,m.name,m.safe?'#85cf7c':state.visited.includes(m.id)?'#d2bd8e':'#8c9e89');for(const b of BOT_BASES)marker(b.x,b.z,b.raided?'×':'⌂',b.raided?'#a68a6b':'#a56a54');marker(-7,-5,'ЛАГЕРЬ','#c9c9a5');marker(-31,-31,'ПЕРЕДАТЧИК','#dda06e');for(const b of state.buildings)if(b.kind==='foundation')marker(b.x,b.z,'УКРЫТИЕ','#a6bc82');marker(state.position.x,state.position.z,'ТЫ','#ee8b51');ctx.save();ctx.translate(ox+state.position.x*unit,oz+state.position.z*unit);ctx.rotate(-state.yaw);ctx.fillStyle='#ee8b5177';ctx.beginPath();ctx.moveTo(0,0);ctx.lineTo(-8,-19);ctx.lineTo(8,-19);ctx.closePath();ctx.fill();ctx.restore();ctx.fillStyle='#aaba93';ctx.font='11px Arial';ctx.fillText('N ↑',560,27);ctx.font='8px Arial';ctx.fillStyle='#92a883';ctx.fillText('ШИРИНА ОСТРОВА '+MAP_SIZES[state.size].width+' м',23,496);for(const m of state.markers||[])marker(m.x,m.z,'⚑ '+m.label,'#f8d46e');
}
$('map-canvas').addEventListener('click',e=>{const rect=e.currentTarget.getBoundingClientRect(),x=((e.clientX-rect.left)/rect.width*600-300)*WORLD_RADIUS/235,z=((e.clientY-rect.top)/rect.height*520-260)*WORLD_RADIUS/235;if(Math.hypot(x,z)>WORLD_RADIUS)return;state.markers??=[];if(state.markers.length>=16){toast('Уже 16 меток. Удали ненужную.');return;}state.markers.push({x,z,label:$('marker-name').value.trim()||'Метка '+(state.markers.length+1)});drawMap();saveGame();});
