function containerCells(loot){const cells=[];for(const [id,total]of Object.entries(loot))for(let left=total;left>0;left-=stackLimit(id)){const count=Math.min(left,stackLimit(id));cells.push(`<div class="container-slot"><button data-take="${id}" data-amount="${count}" title="${ITEMS[id].name}">${art(id)}<b>×${count}</b><small>${ITEMS[id].name}</small></button><button class="take-one" data-take="${id}" data-amount="1" aria-label="Взять один ${ITEMS[id].name}">+1</button></div>`);}const building=state.buildings.find(b=>b.id===activeContainer),limit=isCupboard04()?24:building?.kind==='largeStorage'?30:building?.kind==='storage'?12:Math.max(12,cells.length);while(cells.length<limit)cells.push('<div class="container-slot empty-cell"></div>');return cells.join('');}
function furnacePane(){const f=furnaceFor(state,activeFurnace);return `<aside class="container-loot furnace-pane"><h3>ПЕЧЬ</h3><p>Положи дерево и одну или две разные руды. Плавка включается автоматически, обе руды обрабатываются вместе. Выход забирается вручную.</p>${[['ТОПЛИВО',[0]],['РУДА',[1,2]],['РЕЗУЛЬТАТ',[3,4,5]]].map(([name,indices])=>`<h4>${name}</h4><div class="furnace-row">${indices.map(i=>{const a=f.slots[i];return `<button data-furnace-slot="${i}" title="${a?ITEMS[a.item].name:i===0?'Древесина':i<3?'Руда':'Выход'}">${a?art(a.item):icon(i===0?'wood':i<3?'ore':'storage')}<b>${a?.count||''}</b><small>${a?ITEMS[a.item].name:i===0?'ДЕРЕВО':i<3?'ВХОД':'ВЫХОД'}</small></button>`;}).join('')}</div>`).join('')}<div class="smelt-progress"><i style="width:${f.progress/4*100}%"></i></div><button id="furnace-toggle" class="${f.on?'burning':''}">${f.on?'ОСТАНОВИТЬ':'РАЗЖЕЧЬ ПЕЧЬ'}</button><p>${f.on?'ПЛАВКА · 4 СЕК / РУДА':'ОСТАНОВЛЕНО · НУЖНЫ ДЕРЕВО, РУДА И МЕСТО НА ВЫХОДЕ'}</p></aside>`;}
