function groundBag(position=state.position){state.groundBags??=[];state.containers??={};let bag=state.groundBags.find(b=>!state.depleted.includes(b.id)&&Math.hypot(b.x-position.x,b.z-position.z)<3);if(!bag){bag={id:'drop-'+Date.now()+'-'+state.groundBags.length,x:position.x-Math.sin(state.yaw)*1.4,z:position.z-Math.cos(state.yaw)*1.4};if(state.groundBags.length>=500){bag=state.groundBags[state.groundBags.length-1];state.depleted=state.depleted.filter(id=>id!==bag.id);}else state.groundBags.push(bag);}state.containers[bag.id]??={};return bag;}

