function stopPad(e){if(e.pointerId!==padPointer)return;padPointer=null;touch.x=touch.z=0;$('move-knob').style.transform='';}pad.addEventListener('pointerup',stopPad);pad.addEventListener('pointercancel',stopPad);
document.addEventListener('keydown',e=>{if(mode==='playing'&&!activeOverlay&&(e.ctrlKey||e.code==='ControlLeft'||e.code==='ControlRight'))e.preventDefault();
 if(e.code==='Escape'){e.preventDefault();if(activeOverlay==='settings')closeSettings();else if(activeOverlay)closeOverlay();else if(mode==='playing')openOverlay('pause');return;}
 if(activeOverlay){if(e.code==='Tab'){const focusable=[...$(activeOverlay).querySelectorAll('button:not([disabled]),input,summary,a')].filter(el=>el.offsetParent!==null);const i=focusable.indexOf(document.activeElement);if(focusable.length){e.preventDefault();focusable[(i+(e.shiftKey?-1:1)+focusable.length)%focusable.length].focus();}}return;}
 if(mode!=='playing')return;if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();keys.add(e.code);if(e.repeat)return;
 if(isBuilding()&&isFoundation(currentBuild())&&['KeyQ','KeyZ'].includes(e.code)){adjustFoundation(e.code==='KeyQ'?.5:-.5);return;}if(e.code==='KeyE')doAction();if(e.code==='KeyF')doAction(true);if(e.code==='KeyI'||e.code==='Tab'){e.preventDefault();openInventory();}if(e.code==='KeyC')openInventory('craft');if(e.code==='KeyB'){if(state.inventory.plan>0){state.selected='plan';equipSlot(state,'plan');openBuildWheel();}else openInventory('build');}if(e.code==='KeyM')openOverlay('map');if(e.code==='KeyR'){if(isBuilding())rotateBuild();else doReload();}if(e.code==='Space')jump();if(e.code==='KeyT')chooseItem(state.selected==='torch'?'rock':'torch');if(/^Digit[1-6]$/.test(e.code)){const n=Number(e.code.slice(-1))-1;const item=$('hotbar').children[n]?.dataset.item;if(item)chooseItem(item);}
});
document.addEventListener('keyup',e=>keys.delete(e.code));
document.addEventListener('pointerlockchange',()=>{if(document.pointerLockElement===$('world'))lockSettlingUntil=performance.now()+80;if(mode==='playing'&&!activeOverlay)$('look-hint').hidden=document.pointerLockElement===$('world');});
window.addEventListener('blur',()=>{if(mode==='playing'&&!activeOverlay){focusPaused=true;saveGame();openOverlay('pause');}});window.restoreOskolFocus=()=>{if(focusPaused&&mode==='playing'&&activeOverlay==='pause'){focusPaused=false;closeOverlay();}};
function pauseNative(){if(mode==='playing'){saveGame();if(!activeOverlay){focusPaused=true;openOverlay('pause');}}}
window.pauseLayer=pauseNative;window.pauseOskol=pauseNative;window.layerBack=()=>{if(activeOverlay==='settings'){closeSettings();return true;}if(activeOverlay){closeOverlay();return true;}if(mode==='playing'){openOverlay('pause');return true;}return false;};
document.addEventListener('visibilitychange',()=>{if(document.hidden)pauseNative();lastTime=performance.now();});window.addEventListener('pagehide',()=>saveGame());
function checkRotate(){$('rotate-warning').hidden=!(mode==='playing'&&window.matchMedia('(pointer:coarse)').matches&&window.innerHeight>window.innerWidth&&!document.body.classList.contains('portrait-okay'));}
$('portrait-play').addEventListener('click',()=>{document.body.classList.add('portrait-okay');checkRotate();});window.addEventListener('resize',()=>{world?.resize();checkRotate();});
window.addEventListener('oskol-context-lost',()=>{pauseNative();$('fatal').hidden=false;$('fatal-text').textContent='Видеоконтекст потерян. Прогресс сохранён, если хранилище доступно. Перезагрузи игру; при повторении выбери более низкую графику.';});
function moveBoat(dt,x,z){const boat=world.boats.find(b=>b.id===state.boat);if(!boat){delete state.boat;return 0;}const speed=9,nx=state.position.x+(x*Math.cos(state.yaw)+z*Math.sin(state.yaw))*speed*dt,nz=state.position.z+(-x*Math.sin(state.yaw)+z*Math.cos(state.yaw))*speed*dt;if(Math.hypot(nx,nz)<WORLD_RADIUS*1.48&&terrainHeight(nx,nz)<waterLevelAt(nx,nz)-.2){state.position.x=nx;state.position.z=nz;}boat.x=state.position.x;boat.z=state.position.z;boat.model.position.set(boat.x,waterLevelAt(boat.x,boat.z)+.12,boat.z);boat.model.rotation.y=state.yaw;state.boatState??={};state.boatState[boat.id]={x:boat.x,z:boat.z};motor.reset(waterLevelAt(boat.x,boat.z)+.35);return Math.min(1,Math.hypot(x,z));}
function leaveBoat(){let spot=null;for(const m of MONUMENTS)if(m.dock&&Math.hypot(state.position.x-m.dock.x,state.position.z-m.dock.z)<14)spot=m.dock;for(let r=3;!spot&&r<45;r+=3)for(let i=0;i<24;i++){const x=state.position.x+Math.cos(i/24*Math.PI*2)*r,z=state.position.z+Math.sin(i/24*Math.PI*2)*r;if(terrainHeight(x,z)>waterLevelAt(x,z)+.4&&Math.hypot(x,z)<WORLD_RADIUS){spot={x,z,y:terrainHeight(x,z)};break;}}if(!spot){toast('Подплыви ближе к берегу или нижнему причалу нефтеплатформы.');return;}delete state.boat;state.position={x:spot.x,z:spot.z};motor.reset(spot.y);cameraFeetY=motor.y;saveGame();}
function frame(time){
 const rawDt=lastTime?Math.max(0,(time-lastTime)/1000):1/60,dt=Math.min(rawDt,.1);lastTime=time;lastFrameMs=rawDt*1000;smoothedFps+=(1/Math.max(.001,rawDt)-smoothedFps)*.02;
 const running=mode==='playing'&&!activeOverlay&&!state.dead&&$('rotate-warning').hidden;
 if(ready){
  if(running){
   attackCooldown=Math.max(0,attackCooldown-dt);if(automaticHeld&&isGun(state.selected)&&WEAPONS[state.selected].automatic&&attackCooldown===0)doAction(true);let x=(keys.has('KeyD')||keys.has('ArrowRight')?1:0)-(keys.has('KeyA')||keys.has('ArrowLeft')?1:0)+touch.x,z=(keys.has('KeyS')||keys.has('ArrowDown')?1:0)-(keys.has('KeyW')||keys.has('ArrowUp')?1:0)+touch.z;const len=Math.hypot(x,z);if(len>1){x/=len;z/=len;}
   state.crouched=keys.has('ControlLeft')||keys.has('ControlRight')||touch.crouch||!world.canStand04(state,motor.y);const sprint=(keys.has('ShiftLeft')||keys.has('ShiftRight')||touch.sprint)&&z<-.1&&Math.abs(x)<.18&&!state.crouched;
   const moving=state.boat?moveBoat(dt,x,z):motor.step(dt,{x,z,yaw:state.yaw,sprint,crouch:state.crouched,water:terrainHeight(state.position.x,state.position.z)<waterLevelAt(state.position.x,state.position.z)+.3},state.position,{floor:(x,z,y)=>world.floorHeight(x,z,state,y),canMove:(x,z,y)=>world.canMove(x,z,state,y)});
   state.feetY=motor.y;jumpHeight=motor.grounded?0:.5;
   if(!Number.isFinite(cameraFeetY))cameraFeetY=motor.y;cameraFeetY+=(motor.y-cameraFeetY)*(1-Math.exp(-20*dt));
   world.camera.position.set(state.position.x,cameraFeetY+(state.crouched?1.05:1.72)+(moving&&motor.grounded?Math.sin(playTime*(sprint?12:8))*.018:0),state.position.z);world.camera.rotation.set(state.pitch,state.yaw,0,'YXZ');playTime+=dt;
   const nearFire=world.fires.some(f=>Math.hypot(f.x-state.position.x,f.z-state.position.z)<4),inWater=!state.boat&&motor.y<waterLevelAt(state.position.x,state.position.z)-1.1;tick(state,dt,{sprinting:sprint,nearFire,inWater});
   stepTimer-=dt;if(moving>.15&&jumpHeight<=.01&&stepTimer<=0){audio.step();stepTimer=sprint?.30:.47;}
   world.state04=state;advanceReload04();if(advanceMaintenance(state,dt,world.staticStructures))world.syncDecay(state);for(const f of fireZones04){f.left-=dt;if(Math.hypot(state.position.x-f.x,state.position.z-f.z)<2)takeDamage(dt*5,'explosion');}fireZones04=fireZones04.filter(f=>f.left>0);world.update(dt,state,true,{moving,damage:takeDamage});const site=monumentAt(state.position.x,state.position.z);if(site&&!state.visited.includes(site.id)){state.visited.push(site.id);toast('ОТКРЫТО РТ: '+site.name+' · '+state.visited.length+'/'+MONUMENTS.length,4);audio.pickup();}uiTimer+=dt;saveTimer+=dt;if(uiTimer>.16){uiTimer=0;updateHUD();}if(saveTimer>15){saveTimer=0;saveGame();}
   if(state.dead){saveGame();openOverlay('death');}
  }else if(mode==='playing'&&activeOverlay==='inventory'&&activeFurnace&&!document.hidden){advanceFurnaces(state,dt);machineTimer+=dt;if(machineTimer>.2){machineTimer=0;const pane=$('inventory-content').querySelector('.furnace-pane');if(pane)pane.outerHTML=furnacePane();}}else if(mode==='front'&&!activeOverlay){world.menuCamera(time/1000);world.update(dt,state,false);}
  if(mode==='front'&&!activeOverlay||running||world.needsRender){world.render();lastRendered=time;}
 }
 if(time>toastUntil)$('toast').classList.remove('show');pickupTimers=pickupTimers.filter(p=>{if(time>p.until){p.el.remove();return false;}return true;});requestAnimationFrame(frame);
}
$('fatal').querySelector('button').addEventListener('click',()=>location.reload());
